\label{localclassintro}
Assume $n=2$, $F>0$ constant, and that $x_0$ is a triple junction point for  a minimizer $U \in \mathcal A$ of $J(\cdot, F)$. Then in $B_{r_0}(x_0)$, for some $r_0$ small, $\Gamma(U)$ consists of three $C^{1,\alpha}$ curves starting at $x_0$ and meeting at either $120^\circ$ angles, or at $\theta_i$, $i=1,2,3$ angles obtained from $F$ by the compatibility equation
\begin{equation}\label{uofintro}
 f^1\tan\theta_1=f^2\tan\theta_2=f^3\tan\theta_3, \quad \sum \theta_i=2\pi, \quad \theta_i \in (\frac \pi 2, \pi).
 \end{equation}

\label{pert}
Let $U \in \mathcal A $ minimize $J(\cdot, F)$ in $B_1$, $F\in L^\infty(B_1)$, satisfy $$\|U\|_{L^\infty(B_1)} \leq 1.$$ Assume that for some $\mu>0$
\begin{equation}\label{mu0}
|U(\frac 1 2 e_n)| \geq \mu .
\end{equation}
 Then, there exists $\varepsilon>0$ depending on $\mu$ such that if 
\begin{equation}\label{flatnew} \Gamma(U) \subset \{|x_n| \leq \varepsilon\}, \quad  \|F\|_{L^\infty(B_1)} \leq \varepsilon,\end{equation} with $0\in \Gamma(U)$ then, up to relabeling the indices, 
$$u^i \equiv 0 \quad \text{in $B_{1/2}$, for all $i \geq 3$,}$$
and $\Gamma(U)$ is $C^{1,\alpha}$ in $B_{1/2}$, for all $0<\alpha <1,$ with $$|\nabla u^1| = |\nabla u^2| \quad \text{on $\Gamma(U)$.}$$

\label{prop:asympt}
Let $U \in \mathcal A$ minimize $J(\cdot, F)$ in $B_1$, for $F \in L^\infty(B_1)$. Assume $0 \in \Gamma(U)$. Then, as $x \to 0$, either $$|U(x)| = o(|x|)$$ or 
$$|U(x)| = a |x \cdot \nu| + o(|x|)$$ for some $a>0$ and $\nu \in \partial B_1.$ In the latter case, the conclusion of Proposition \ref{pert} holds and $U \in C^{1,\alpha}$ in a neighborhood of $0.$

\label{duv}
Let $U,V \in \mathcal A$ be continuous and satisfy the Euler-Lagrange equations 
\begin{equation}\label{EL2}\Delta u^i \geq f^i \chi_{\{u^i>0\}}, \quad \Delta \hat u^i \leq \hat f_U^i, \quad \text{in $B_1,$}\end{equation}
\begin{equation}\label{EL3}\Delta v^i \geq f^i \chi_{\{v^i>0\}}, \quad \Delta \hat v^i \leq \hat f_V^i, \quad \text{in $B_1,$}\end{equation}
with $F\in L^\infty$ and $f^i \geq 0$. Then $d(U,V)$ is subharmonic in $B_1$.

\label{stability} 
Let $U,V$ be as in Lemma \ref{duv}
and assume that $d(U,V) \leq \varepsilon$ on $\partial B_1$. Then  $d(U,V) \leq \varepsilon$ in $B_1.$
In particular if  $U=V$ on $\partial B_1,$ then $U=V$ in $B_1.$

\label{Appppp} The same proof shows that, if $V$ satisfies \eqref{EL3} with right hand side $H$, then 
\begin{equation}\label{app}
\Delta d(U,V) \geq - \|F-H\|_\infty.
\end{equation}

\label{almgren}
Let $U$ be a minimizer of $J_0(\cdot):=J(\cdot, 0)$ in $B_1$. Then,
$$\gamma(r):= \frac{r\int_{B_r}|\nabla U|^2dx}{\int_{\partial B_r}|U|^2}$$ is monotone increasing and if it is constant $U$ is homogeneous of degree $\gamma$.

\label{blowup}Let $U \in \mathcal A$ be a global minimizer to $J(\cdot, F)$, $F$ constant. Assume that \begin{equation}\label{limit} \liminf_{r\to\infty} \frac{a_r}{r^2} < \infty.\end{equation}
Then, there exists $r_j \to \infty$, $j \to \infty$, such that 
$$U_{j}(x):=\frac{U(r_jx)}{r_j^2} \to U^F_0(x),$$ uniformly on compact sets, where $U_0^F$ is a minimizer to $J(\cdot, F)$ which is homogeneous of degree 2.

\label{linearsmooth}We remark that solutions in a neighborhood of a ray are smooth up to the ray, on either side of the ray. This is because solutions to a general transmission problem (in $\mathbb R^n$) across a hyperplane ($x=(x',x_n)$), 
\begin{align*}
& \Delta v = 0 \quad \text{in $B_1 \cap \{x_n\neq 0\}$}\\
& v_n^++v_n^-=h(x')v \quad \text{on $B_1 \cap \{x_n=0\}$}\end{align*}
can be reduced to the Neumann problem in a half-space for the function $$\frac 1 2 v(x', x_n) + \frac 1 2 v(x', -x_n).$$ In particular, if $h$ is smooth then solutions are smooth on both sides of the hyperplane.

\label{extend} Let $V \in \mathcal D$ be a bounded double-valued classical solution in $B_1\setminus \{0\}$ to \begin{align}\label{FBlinear2}
& \Delta V=0 & \text{in $\{U_0\neq 0\}$}\\
\label{b}& V_{\nu^+} + V_{\nu^-} \geq 0 & \text{on $\{U_0=0\} \cap \{V \geq 0\}.$}
\end{align} 

Then 
\begin{equation}\label{|V|}
\text{$|V|$ is subharmonic in $B_1$,}\end{equation}
\begin{equation}\label{V0}|V(x)| \leq C |x|^\alpha \|V\|_\infty,\end{equation}
and hence $V$ is continuous at zero with a H\"older modulus of continuity.
In particular, any solution to \eqref{FBlinear}-\eqref{transmission} is uniquely determined by its boundary values on $\partial B_1.$

We look for homogeneous solutions to \eqref{FBlinear}, 
$r^\lambda g(\theta),$ with \begin{equation}\label{g}\text{$g$ periodic of period $4\pi$ and $g(\theta+2\pi) = - g(\theta)$.}\end{equation} 
Then,
\begin{equation}
g'' + \lambda^2 g=0 \quad \text{except for $\theta_k=(2k+1)\frac{\pi}{3},$ $k \in \mathbb Z$}
\end{equation}
and at these points $g$ satisfies the jump condition,
\begin{equation}\label{g'}
(g')^+ - (g')^- = \frac{4}{\sqrt 3} g,
\end{equation} where $(g')^\pm$ denote the limits of $g'$ from the right and  the left respectively. 
Hence, on each interval $[\theta_k, \theta_{k+1}]$, $g=g_k$ has the form
\begin{equation}\label{gk}
g_k(\theta) = a_k\cos(\lambda \theta) + b_k \sin(\lambda \theta)
\end{equation}
and the jump condition implies that $g_{k+1}$ is obtained from $g_k$ from the formula, 
\begin{equation}
g_{k+1} (\theta) = g_k (\theta) + \frac{4}{\lambda \sqrt 3} g_{k}(\theta_{k+1}) \sin(\lambda(\theta-\theta_{k+1})).
\end{equation}
The eigenvalues and corresponding eigenfunctions $\lambda^2_m, g_m$ can be obtained by the standard min-max of the Rayleigh quotient 
\begin{equation}\label{quotient}
    \min \max_{g\in V_m}\frac{\int_0^{4\pi} (g')^2d\theta + 4/\sqrt 3 \sum_{0}^{5}g^2(\theta_k)}{\int_0^{4\pi} g^2d\theta}\end{equation}
where $V_m$ is a $m$-dimensional subspace of the $L^2$ space of functions satisfying \eqref{g}. Notice that there is a one-to-one correspondence  between the homogeneity $\lambda$ and the eigenvalue $\lambda^2.$



The analogous approach without the extra addend involving the values at the jumps, produces the standard homogeneities $1/2, 3/2, 5/2, \ldots$ of multiplicity 2, with corresponding eigenfunctions
\begin{equation}\label{zeroeigen}\cos \frac{\theta}{2},\sin \frac{\theta}{2}, \cos \frac{3\theta}{2}, \sin \frac{3\theta}{2},  \ldots\end{equation}
The eigenvalues for our problem are larger than these ones,
thus in particular, the fifth homogeneity (counted with multiplicity) is larger than 5/2. On the other hand the first four homogeneities are explicit, and they are $1,1, 3/2$ and $2$, and they correspond to 
$$\partial_{x_1}U_0, \partial_{x_2}U_0, r^{3/2} \cos\frac{3\theta}{2}, \partial_\theta U_0,$$
restricted to the unit circle.

Now the result follows by standard Fourier decomposition. Precisely, given a continuous boundary data $g(\theta)$ on $\partial B_1$ satisfying \eqref{g}, we can write the Fourier expansion relative to the orthonormal basis of $L^2(\partial B_1)$ given by the eigenfunctions $g_m$'s, $$g= \sum_m a_m g_m(\theta) \quad \text{in $L^2(\partial B_1)$}.$$
Then, solution to \eqref{FBlinear} with boundary data $g$ is given by 
$$V= \sum_m a_m r^{\lambda_m}g_m(\theta) \quad \text{in $L^2(B_1).$}$$
where we deduced that the $L^2$ convergence of the boundary data implies the $L^2$ convergence in the interior by \eqref{|V|}. The result follows since
$$|a_m| \leq \|g\|_2, \quad \|g_m\|_\infty \leq C \quad \text{by \eqref{gk}},$$ for $C$ universal.

\label{zero} Let $U$ minimize $J(\cdot, F)$ in $B_1$ with $F \geq 0$. There exist $\varepsilon_0, \rho>0$ universal such that if for some $\varepsilon \leq \varepsilon_0$




\begin{equation}\label{ass1}d(U,\mathcal U_0) \leq \varepsilon, \quad \|F\|_{\infty} \leq \varepsilon^2 \quad \text{in $B_1$,}\end{equation} 
then $$d(U,(1+\varepsilon p)\tilde {\mathcal U}_{0}) \leq \frac \varepsilon 2 \rho^{3/2} \quad \text{in $B_\rho(\varepsilon\bar{\bf m})$},$$ with $\tilde {\mathcal U}_0$ a rotation by $\varepsilon q$ and translation by $\varepsilon \bar{\bf m}$ of $\mathcal U_{0},$ with $|\bar{\bf m}|, |p|$ and $|q| \leq C.$

\label{G} There exists a global $C^{1,1}$ (double-valued) function $G$ that has the asymptotic expansion
$$G=U^F_0+ |x|^{\lambda_3}g^F_3(\theta) + O(|x|^{2\lambda_3-2}), \quad |x| \geq 1$$ such that it solves the original problem with an error $O(|x|^{2\lambda_3-4})$. That is, if the $g^i$'s denote the restriction of $|G|$ (which is single-valued) to the three connected components of $|G|>0$, then 
\begin{equation}\label{improvederror}
    \Delta g^i=f_i \chi_{\{g^i>0\}}+ O(|x|^{2\lambda_3-4}).\end{equation}

\label{extendnew} Let $V \in \mathcal D$ be a bounded solution to \eqref{FBlinearnew}-\eqref{transmissionnew}in $ \mathcal C_1\setminus \{0'\}.$ 
Then, for some $\alpha>0$ small,  
\begin{equation}\label{V0new}|V(x)| \leq C |x'|^\alpha \|V\|_\infty \quad \mbox{in} \quad \mathcal C_{1/2} \setminus \{0'\},\end{equation}
hence $V$ can be extended continuously on the line $\{0'\} \times B_1''$ with zero value. Moreover, 
\begin{equation}\label{complete}
    \|V\|_{C^{\alpha}(\mathcal C_{1/2})} \leq C \|V\|_{L^\infty(\mathcal C_1)}.
\end{equation}

\label{expandV2} 
Let $V \in \mathcal D$ be a bounded solution to \eqref{FBlinearnew}-\eqref{transmissionnew}in $ \mathcal C_1\setminus \{0'\}.$ 
Then, for $\alpha$ given in Lemma \ref{extendnew}, 


\begin{equation}\label{Vx}V(x)=({\bf m}+ M x'') \cdot \nabla U^F_0 + p |x'|^{\lambda_3}g_3^F(\theta) + q \partial_\theta U^F_0 + O(|x|^{2+\alpha}),\end{equation}
where $M$ is a linear map from the $x''$ to the $x'$ variables, and $\|M\|$, $|{\bf m}|, |p|$ and $|q|$ are universally bounded.

Equations \eqref{V0new}-\eqref{complete} is invariant under translations in the $x''$ direction. Thus, by using discrete differences and iterating \eqref{complete} we obtain that all the $x''$-derivatives satisfy \eqref{V0new}-\eqref{complete}, that is 
\begin{equation}\label{V0newder}|D^k_{x''}V(x)| \leq C |x'|^\alpha \|V\|_\infty \quad \mbox{in} \quad \mathcal C_{1/2},\end{equation}
and
\begin{equation}\label{completeder}
    \|D^k_{x''}V\|_{C^{\alpha}(\mathcal C_{1/2})} \leq C(k) \|V\|_{L^\infty(\mathcal C_1)}.
\end{equation}
This means that $V(x',0)$ solves the linearized problem in 2D 
\begin{align}\label{9}
& \Delta_{x'} V= \Phi & \text{in $\{U_0^F\neq 0\}$}\\
\label{10} & V_{\nu^+} + V_{\nu^-} =\frac{a^F}{|\nabla U_0^F|} V & \text{on $\{U_0^F=0\}.$}
\end{align}
and $$\Phi=-\Delta_{x''} V(x',0) \in \mathcal D,$$ and by \eqref{V0newder}-\eqref{completeder} \begin{equation}\label{00}|\Phi| \leq C|x'|^\alpha, \quad \|\Phi\|_{C^{\alpha}(\mathcal C_{1/2})} \leq C.\end{equation}

\medskip
\noindent
{\it Claim:} Solutions to \eqref{9}-\eqref{10} satisfy the same expansion as solutions to the 2D homogeneous problem (that is $\Phi=0$) with an error of order $O(|x'|^{2+\alpha}).$ 

Indeed, when we compare in $B_r'$ our solution with the solution to the homogeneous problem and the same boundary data on $\partial B'_r$, their difference is bounded by $Cr^{2}\|\Phi\|_\infty \leq Cr^{2+\alpha}$ by the maximum principle. This is because the absolute value of the difference, which is single-valued, has Laplacian bounded below  by $-\|\Phi\|_\infty$, as the distributional part along the rays is nonnegative due to the fact that $a_F\ge 0$ in the transmission condition. This means that the Campanato method of successive iterations gives the desired claim. Therefore, (see Lemma \ref{L8.2}),
$$V(x',0)=V_{{\bf m}, p, q}^F + O(|x'|^{2+\alpha}).$$ In the same way, by the translation invariance, also the derivatives in the $x''$ direction have a similar expansion, hence 
$$D_{x''}V(x',0)= \nabla U_0^F \cdot M + O(|x'|^{1+\alpha}),$$ for some linear map $M$ from the $x''$ to the $x'$ variables. Since 
$$D_{x''}^2V=O(|x'|^{\alpha}),$$ we can integrate in the $x''$-direction and obtain the desired expansion.

\label{expandV20} 
Let $V \in \mathcal D$ be a bounded solution to \eqref{FBBB}-\eqref{transmissionBBB} in $ \mathcal C_1\setminus \{0'\}.$ 
Then, 
\begin{equation}\label{Vx2}V(x)=({\bf m}+ M x'') \cdot \nabla U_0 + p \mathcal U_0 + q \partial_\theta \mathcal U_0 + O(|x|^{2+\alpha}),\end{equation}
where $M$ is a linear map from $x''$ to $x'$, $\|M\|$, $|{\bf m}|, |p|$ and $|q|$ are universally bounded.

\label{zeron} Let $U$ minimize $J(\cdot, F)$ in $B_1$ with $F \geq 0$. There exist $\varepsilon_0, \rho>0$ universal such that if for some $\varepsilon \leq \varepsilon_0$
\begin{equation}\label{ass01}d(U,\mathcal U_0) \leq \varepsilon, \quad \|F\|_{\infty} \leq \varepsilon^2 \quad \text{in $B_1$,}\end{equation} 
then $$d(U,(1+\varepsilon p)\tilde {\mathcal U}_{0}) \leq \frac \varepsilon 2 \rho^{3/2} \quad \text{in $B_\rho(\varepsilon \bar{\bf m})$},$$ with $\tilde {\mathcal U}_0$ a rigid motion in $\mathbb R^n$ (a rotation $O_{\varepsilon A}$ and translation by $\varepsilon \bar{\bf m}$) of $\mathcal {U}_{0},$ and $|A|,|\bar{\bf m}|,|p| \leq C$, $C$ universal.
